// Package miget is a Go client for the Miget PaaS REST API.
//
// The SDK is generated by hand from the published OpenAPI 3.0 specification
// (see openapi/openapi.json) and covers all documented operations. Create a
// client with New or NewFromEnv and access the API through the service
// fields, for example:
//
//	client := miget.New(os.Getenv("MIGET_API_TOKEN"))
//	apps, err := client.Apps.List(ctx)
package miget

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
)

// Version is the version of the miget-go SDK.
const Version = "0.1.0"

// EnvAPIToken is the environment variable read by NewFromEnv.
const EnvAPIToken = "MIGET_API_TOKEN"

const (
	defaultBaseURL    = "https://app.miget.com"
	headerWorkspaceID = "X-Workspace-Id"
)

// Client is the Miget API client. Use New or NewFromEnv to create one.
//
// All API operations are exposed through the service fields (Apps, Projects,
// ...). A Client is safe for concurrent use by multiple goroutines.
type Client struct {
	httpClient  *http.Client
	baseURL     string
	token       string
	workspaceID string
	userAgent   string

	// Services, grouped by OpenAPI tag.

	Apps                *AppsService                // tag: Apps
	Projects            *ProjectsService            // tag: Projects
	ProjectVars         *ProjectVarsService         // tag: Project Environment Variables
	Resources           *ResourcesService           // tag: Resources
	Services            *ServicesService            // tag: Services
	Buckets             *BucketsService             // tag: Buckets
	BucketObjects       *BucketObjectsService       // tag: Bucket Objects
	Addons              *AddonsService              // tag: App Add-ons
	Deployments         *DeploymentsService         // tag: App Deployments
	Domains             *DomainsService             // tag: App Domains
	Vars                *VarsService                // tag: App Environment Variables
	Cronjobs            *CronjobsService            // tag: App Cron Jobs
	Ports               *PortsService               // tag: App Ports
	Auth                *AuthService                // tag: Authentication
	Users               *UsersService               // tag: Users
	SSHKeys             *SSHKeysService             // tag: Users - SSH Keys
	Credits             *CreditsService             // tag: Users - Credits
	Plans               *PlansService               // tag: Plans
	Regions             *RegionsService             // tag: Regions
	Components          *ComponentsService          // tag: Components
	RegistryCredentials *RegistryCredentialsService // tag: Container Registry Credentials
}

// Option configures a Client.
type Option func(*Client)

// WithBaseURL overrides the API base URL (default https://app.miget.com).
// The spec paths already include the /api/v1 prefix, so the base URL must
// not include it.
func WithBaseURL(baseURL string) Option {
	return func(c *Client) { c.baseURL = strings.TrimRight(baseURL, "/") }
}

// WithWorkspaceID sets the X-Workspace-Id header on every request,
// selecting the workspace the API operates on.
func WithWorkspaceID(workspaceID string) Option {
	return func(c *Client) { c.workspaceID = workspaceID }
}

// WithHTTPClient sets the underlying *http.Client. Note that a client with
// a Timeout will also cut off long-lived log streams (StreamLogs); prefer
// per-request context deadlines.
func WithHTTPClient(httpClient *http.Client) Option {
	return func(c *Client) {
		if httpClient != nil {
			c.httpClient = httpClient
		}
	}
}

// WithUserAgent overrides the User-Agent header (default "miget-go/<version>").
func WithUserAgent(userAgent string) Option {
	return func(c *Client) { c.userAgent = userAgent }
}

// New returns a Client authenticating with the given token. The token is a
// Miget API token (miget_live_...) or a short-lived JWT obtained from
// Auth.SignIn, and is sent as "Authorization: Bearer <token>".
func New(token string, opts ...Option) *Client {
	c := &Client{
		httpClient: &http.Client{},
		baseURL:    defaultBaseURL,
		token:      token,
		userAgent:  "miget-go/" + Version,
	}
	for _, opt := range opts {
		opt(c)
	}

	c.Apps = &AppsService{client: c}
	c.Projects = &ProjectsService{client: c}
	c.ProjectVars = &ProjectVarsService{client: c}
	c.Resources = &ResourcesService{client: c}
	c.Services = &ServicesService{client: c}
	c.Buckets = &BucketsService{client: c}
	c.BucketObjects = &BucketObjectsService{client: c}
	c.Addons = &AddonsService{client: c}
	c.Deployments = &DeploymentsService{client: c}
	c.Domains = &DomainsService{client: c}
	c.Vars = &VarsService{client: c}
	c.Cronjobs = &CronjobsService{client: c}
	c.Ports = &PortsService{client: c}
	c.Auth = &AuthService{client: c}
	c.Users = &UsersService{client: c}
	c.SSHKeys = &SSHKeysService{client: c}
	c.Credits = &CreditsService{client: c}
	c.Plans = &PlansService{client: c}
	c.Regions = &RegionsService{client: c}
	c.Components = &ComponentsService{client: c}
	c.RegistryCredentials = &RegistryCredentialsService{client: c}
	return c
}

// NewFromEnv returns a Client using the token from the MIGET_API_TOKEN
// environment variable. It returns an error if the variable is unset or
// empty.
func NewFromEnv(opts ...Option) (*Client, error) {
	token := os.Getenv(EnvAPIToken)
	if token == "" {
		return nil, fmt.Errorf("miget: environment variable %s is not set", EnvAPIToken)
	}
	return New(token, opts...), nil
}

// Ptr returns a pointer to v. It is a convenience helper for setting
// optional pointer fields on request structs:
//
//	req := &miget.UpdateAppRequest{Maintenance: miget.Ptr(true)}
func Ptr[T any](v T) *T { return &v }

// newRequest builds an *http.Request for the given API path (which must
// include the /api/v1 prefix, as in the OpenAPI spec).
func (c *Client) newRequest(ctx context.Context, method, path string, query url.Values, body any) (*http.Request, error) {
	u := c.baseURL + path
	if len(query) > 0 {
		u += "?" + query.Encode()
	}

	var reader io.Reader
	if body != nil {
		data, err := json.Marshal(body)
		if err != nil {
			return nil, fmt.Errorf("miget: encoding request body: %w", err)
		}
		reader = bytes.NewReader(data)
	}

	req, err := http.NewRequestWithContext(ctx, method, u, reader)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+c.token)
	req.Header.Set("Accept", "application/json")
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.workspaceID != "" {
		req.Header.Set(headerWorkspaceID, c.workspaceID)
	}
	if c.userAgent != "" {
		req.Header.Set("User-Agent", c.userAgent)
	}
	return req, nil
}

// do performs a JSON API request. body and out may be nil. Non-2xx
// responses are returned as *APIError.
func (c *Client) do(ctx context.Context, method, path string, query url.Values, body, out any) error {
	req, err := c.newRequest(ctx, method, path, query, body)
	if err != nil {
		return err
	}

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return fmt.Errorf("miget: reading response body: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return newAPIError(resp.StatusCode, data)
	}
	if out == nil || len(bytes.TrimSpace(data)) == 0 {
		return nil
	}
	if err := json.Unmarshal(data, out); err != nil {
		return fmt.Errorf("miget: decoding response: %w", err)
	}
	return nil
}

// doText performs a GET request for a plain-text endpoint and returns the
// response body as a string. Non-2xx responses are returned as *APIError.
func (c *Client) doText(ctx context.Context, path string) (string, error) {
	req, err := c.newRequest(ctx, http.MethodGet, path, nil, nil)
	if err != nil {
		return "", err
	}
	req.Header.Set("Accept", "text/plain")

	resp, err := c.httpClient.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()

	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return "", fmt.Errorf("miget: reading response body: %w", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return "", newAPIError(resp.StatusCode, data)
	}
	return string(data), nil
}
